 internal static GeneratedBuildingDefinitions Load(string path,string sha,uint expectedSetup,IDictionary<string,Entity> templates,SourceMetadataCompatibility compatibility=null){var bytes=AutonomousWorld.PinnedFile(path,sha,4*1024*1024);var j=JObject.Parse(System.Text.Encoding.UTF8.GetString(bytes),new JsonLoadSettings{DuplicatePropertyNameHandling=DuplicatePropertyNameHandling.Error});if(compatibility!=null){compatibility.RequireTarget(expectedSetup);compatibility.RequireDefinitions(sha,j);}if((int?)j["schema_version"]!=(compatibility?.FactoryDomainQualified==true?2:1)||(compatibility==null&&(uint?)j["setup_hash"]!=expectedSetup)||(j["unsupported_values"]as JArray)?.Count!=0)throw new InvalidDataException("Actual setup-bound complete definition export required");var rows=j["definitions"]as JArray;if(rows==null||rows.Count!=(compatibility?.FactoryDomainQualified==true?compatibility.BuildingCount:8))throw new InvalidDataException("Complete qualified building definition domain required");var r=new GeneratedBuildingDefinitions(Path.GetDirectoryName(path),templates);foreach(JObject row in rows){var key=(string)row["key"];var fields=row["fields"]as JObject;if(string.IsNullOrEmpty(key)||fields==null)throw new InvalidDataException("Definition fields/key required");var d=new RuntimeDefinition();foreach(var field in typeof(RuntimeDefinition).GetFields(BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic)){if(field.Name=="SourceMetadataComplete")continue;if(!fields.TryGetValue(field.Name,out var v))throw new InvalidDataException("Missing actual definition field "+field.Name);if(PresentationOnly.Contains(field.Name)){r.PresentationAssetBindings[key+"/"+field.Name]=(JObject)v.DeepClone();continue;}try{field.SetValue(d,r.Decode(v,field.FieldType,key+"/"+field.Name));}catch(Exception error){throw new InvalidDataException("Exact building field decode failed: "+key+"/"+field.Name,error);}}foreach(var name in PresentationOnly)if(fields[name]!=null)r.PresentationAssetBindings[key+"/"+name]=(JObject)fields[name].DeepClone();if(d.Prefab==null||d.Prefab.name!=key||d.HasRunway||d.IsWall)throw new NotSupportedException("Complete ordinary ground definition required");d.SourceMetadataComplete=true;r.Definitions.Add(d);}if(r.Definitions.Select(x=>x.Prefab.name).Distinct(StringComparer.Ordinal).Count()!=(compatibility?.FactoryDomainQualified==true?compatibility.BuildingCount:8))throw new InvalidDataException("Unique definition identities required");return r;}
 internal static GeneratedBuildingDefinitions LoadS073Legacy(string path,string sha,IDictionary<string,Entity> templates,JObject legacySource,string sourceRepositoryRoot){
  var bytes=AutonomousWorld.PinnedFile(path,sha,4*1024*1024);var j=JObject.Parse(System.Text.Encoding.UTF8.GetString(bytes),new JsonLoadSettings{DuplicatePropertyNameHandling=DuplicatePropertyNameHandling.Error});
  if((int?)j["schema_version"]!=1||(string)j["kind"]!="S073LegacyAuthoredBuildingDefinitions"||(string)j["authority"]!="OriginalLegacyPresetConstruction_NoRuntimeRecipeOverlay"||(string)j["catalog_id"]!="S073"||(string)j["preset_path"]!="Assets/Game/Resources/SkirmishIndustrialBasin.asset"||(string)j["building_catalog"]!="Assets/Game/Configs/Skirmish/IndustrialBasin/Construction.asset"||(string)j["unit_catalog"]!="Assets/Game/Configs/Skirmish/UnitRegistry.asset"||(string)j["selected_source"]?["operation_map_id"]!="opmap.skirmish.industrial_basin"||(string)j["selected_source"]?["source_identity_hash"]!="2a2a791e8292a4f458bd603ceb86598aa0ba2ca82db41323bf5bf7c748ec6900"||(bool?)j["mission_world_allocated"]!=false||(bool?)j["full_mission_initialized"]!=false||(bool?)j["native_visual_readiness"]!=false||(j["unsupported_values"]as JArray)?.Count!=0)throw new InvalidDataException("Exact non-world S073 original legacy building source required");
  if(legacySource==null||(string)legacySource["kind"]!="S073LegacyInitialSpawnExternalData"||(string)legacySource["mission"]!="S073")throw new InvalidDataException("Exact S073 legacy initialization source required");
  var expected=new[]{"Building_Barrack","Building_GuardTower","Building_Ammunition_Depot","Building_OilPump","Building_Refinery","Building_Fuel_Bladder"};var requested=(j["requested_keys"]as JArray)?.Values<string>().ToArray();var rows=j["definitions"]as JArray;
  if(requested==null||!requested.SequenceEqual(expected,StringComparer.Ordinal)||rows==null||rows.Count!=expected.Length)throw new InvalidDataException("Exact six-building S073 legacy definition domain required");
  var sourcePins=j["source_pins"]as JObject??throw new InvalidDataException("S073 definition source pins required");var configPins=legacySource["source_artifacts"]?["configuration_asset_sha256"]as JObject??throw new InvalidDataException("S073 original config pins required");
  foreach(var pin in configPins.Properties()){if((string)sourcePins[pin.Name]!=(string)pin.Value)throw new InvalidDataException("S073 definition artifact does not pin current legacy config: "+pin.Name);AutonomousWorld.PinnedFile(Path.Combine(sourceRepositoryRoot,pin.Name.Replace('/',Path.DirectorySeparatorChar)),(string)pin.Value,16*1024*1024);}
  var r=new GeneratedBuildingDefinitions(Path.GetDirectoryName(path),templates);int rowIndex=0;foreach(JObject row in rows){var key=(string)row["key"];var fields=row["fields"]as JObject;if(key!=expected[rowIndex++]||fields==null)throw new InvalidDataException("S073 definition order/fields differ from original Construction catalog");var d=new RuntimeDefinition();foreach(var field in typeof(RuntimeDefinition).GetFields(BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic)){if(field.Name=="SourceMetadataComplete")continue;if(!fields.TryGetValue(field.Name,out var v))throw new InvalidDataException("Missing actual S073 definition field "+field.Name);if(PresentationOnly.Contains(field.Name)){r.PresentationAssetBindings[key+"/"+field.Name]=(JObject)v.DeepClone();continue;}try{field.SetValue(d,r.Decode(v,field.FieldType,key+"/"+field.Name));}catch(Exception error){throw new InvalidDataException("Exact S073 building field decode failed: "+key+"/"+field.Name,error);}}foreach(var name in PresentationOnly)if(fields[name]!=null)r.PresentationAssetBindings[key+"/"+name]=(JObject)fields[name].DeepClone();if(d.Prefab==null||d.Prefab.name!=key||d.HasRunway||d.IsWall)throw new NotSupportedException("Complete ordinary S073 ground definition required");d.SourceMetadataComplete=true;r.Definitions.Add(d);}
  if(r.Definitions.Count!=expected.Length||r.Definitions.Select(x=>x.Prefab.name).Distinct(StringComparer.Ordinal).Count()!=expected.Length)throw new InvalidDataException("Unique S073 source building identities required");
  foreach(var definition in r.Definitions)foreach(var recipe in new[]{definition.SpawnUnitPrefab,definition.SecondarySpawnUnitPrefab,definition.TertiarySpawnUnitPrefab,definition.QuaternarySpawnUnitPrefab})if(recipe!=null&&(!r.Assets.ContainsKey(recipe.name)||!templates.ContainsKey(recipe.name)))throw new InvalidDataException("S073 production recipe prefab is not in the actual imported template namespace: "+recipe.name);
  return r;
 }
 object Decode(JToken token,Type expected,string path){var codecName=(string)token["codec"];if(codecName=="source-asset-reference-v1"){if(expected!=typeof(SourceUnitPrefab))throw new NotSupportedException("Asset reference requires logical source token at "+path);string key=(string)token["key"],assetPath=(string)token["path"],guid=(string)token["guid"];long id=(long)token["local_id"];if(string.IsNullOrEmpty(key)||string.IsNullOrEmpty(assetPath)||guid?.Length!=32||id==0)throw new InvalidDataException("Complete actual asset identity required");var checkedIdentity=SourceUnitPrefab.FromAssetIdentity(key,assetPath,guid,id);if(AssetIdentities.TryGetValue(key,out var existingIdentity)&&!JToken.DeepEquals(existingIdentity,token))throw new InvalidDataException("Conflicting R6 source asset identity "+key);AssetIdentities[key]=(JObject)token.DeepClone();if(Assets.TryGetValue(key,out var prior))return prior;var result=templates.TryGetValue(key,out var template)?new SourceUnitPrefab(key,template):SourceUnitPrefab.FromAssetIdentity(key,assetPath,guid,id);Assets.Add(key,result);return result;}
 if(codecName=="definition-list-v1"){var rows=token["items"]as JArray;if(rows==null||rows.Count>4096)throw new InvalidDataException("Bounded definition list required");Type element=expected.IsArray?expected.GetElementType():expected.GetGenericArguments().Single();var a=Array.CreateInstance(element,rows.Count);for(int i=0;i<rows.Count;i++)a.SetValue(Decode(rows[i],element,path+"/"+i),i);if(expected.IsArray)return a;var list=(IList)Activator.CreateInstance(expected);foreach(var value in a)list.Add(value);return list;}
 if(codecName=="definition-fields-v1"){var value=Activator.CreateInstance(expected);var fields=(JObject)token["fields"];foreach(var f in expected.GetFields(BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic)){if(fields[f.Name]==null)throw new InvalidDataException("Missing exact slot field");f.SetValue(value,Decode(fields[f.Name],f.FieldType,path+"/"+f.Name));}return value;}return codec.Decode(token,expected,path);}
 }
